/*
 * A043732  Numbers whose number of runs in the base-2 representation is
 *          congruent to 4 mod 5.
 * https://oeis.org/A043732
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 52, u16 n <= 52, u32 n <= 52, u64 n <= 52, u128 n <= 52,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by searching for integers whose number of runs in
   the binary representation is congruent to 4 modulo 5. */
#include <stdlib.h>

static seq_t *cache = NULL;      /* array of found terms */
static size_t term_count   = 0;  /* number of terms stored so far */
static size_t cache_cap    = 0;  /* current capacity of the cache */
static seq_t next_candidate = 1; /* next integer to test */
#define INITIAL_CAPACITY 32768   /* sufficient for n ≈ 10 000 */

/* Count the number of runs (maximal blocks of equal bits) in x. */
static inline seq_t count_runs(seq_t x)
{
    if (x == 0)
        return 0;
    seq_t runs  = 1;
    seq_t prev  = x & 1;
    x >>= 1;
    while (x != 0) {
        seq_t cur = x & 1;
        if (cur != prev) {
            ++runs;
            prev = cur;
        }
        x >>= 1;
    }
    return runs;
}

/* Grow the cache to at least 'needed' elements. */
static void ensure_capacity(size_t needed)
{
    if (needed <= cache_cap)
        return;
    size_t new_cap = (needed > cache_cap * 2) ? needed : cache_cap * 2;
    if (new_cap == 0)
        new_cap = INITIAL_CAPACITY;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (tmp == NULL)
        exit(EXIT_FAILURE);
    cache     = tmp;
    cache_cap = new_cap;
}

/* Return the nth term (n ≥ 1) of A043732. */
seq_t a(idx_t n)
{
    if (n == 0)          /* undefined for offset 1; return 0 silently */
        return 0;

    /* Initialise cache on first call */
    if (cache == NULL)
        ensure_capacity(INITIAL_CAPACITY);

    /* Generate terms until we have at least n of them. */
    while (term_count < (size_t)n) {
        if (count_runs(next_candidate) % 5 == 4) {
            if (term_count == cache_cap)
                ensure_capacity(cache_cap * 2 + 1);
            cache[term_count++] = next_candidate;
        }
        ++next_candidate;
    }

    return cache[n - 1];
}
